/* eslint-disable space-in-parens */

import Complex128Array = require( '@stdlib/array/complex128' );
import zlastIndexOfTruthy = require( './index' );


// TESTS //

// The function returns a number...
{
	var x = new Complex128Array( [ 1.0, 2.0, 3.0 ] );

	zlastIndexOfTruthy( x.length, x, 1 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	var x = new Complex128Array( [ 1.0, 2.0, 3.0 ] );

	zlastIndexOfTruthy( '1', x, 1 ); // $ExpectError
	zlastIndexOfTruthy( true, x, 1 ); // $ExpectError
	zlastIndexOfTruthy( false, x, 1 ); // $ExpectError
	zlastIndexOfTruthy( null, x, 1 ); // $ExpectError
	zlastIndexOfTruthy( {}, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a Complex128Array...
{
	var x = new Complex128Array( [ 1.0, 2.0, 3.0 ] );

	zlastIndexOfTruthy( x.length, '1', 1 ); // $ExpectError
	zlastIndexOfTruthy( x.length, true, 1 ); // $ExpectError
	zlastIndexOfTruthy( x.length, false, 1 ); // $ExpectError
	zlastIndexOfTruthy( x.length, null, 1 ); // $ExpectError
	zlastIndexOfTruthy( x.length, {}, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	var x = new Complex128Array( [ 1.0, 2.0, 3.0 ] );

	zlastIndexOfTruthy( x.length, x, '1' ); // $ExpectError
	zlastIndexOfTruthy( x.length, x, true ); // $ExpectError
	zlastIndexOfTruthy( x.length, x, false ); // $ExpectError
	zlastIndexOfTruthy( x.length, x, null ); // $ExpectError
	zlastIndexOfTruthy( x.length, x, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	zlastIndexOfTruthy(); // $ExpectError
	zlastIndexOfTruthy( 3 ); // $ExpectError
	zlastIndexOfTruthy( 3, new Complex128Array( [ 1.0, 2.0, 3.0 ] ) ); // $ExpectError
	zlastIndexOfTruthy( 3, new Complex128Array( [ 1.0, 2.0, 3.0 ] ), 1, {} ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a number...
{
	var x = new Complex128Array( [ 1.0, 2.0, 3.0 ] );

	zlastIndexOfTruthy.ndarray( x.length, x, 1, 0 ); // $ExpectType number
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	var x = new Complex128Array( [ 1.0, 2.0, 3.0 ] );

	zlastIndexOfTruthy.ndarray( '1', x, 1, 1 ); // $ExpectError
	zlastIndexOfTruthy.ndarray( true, x, 1, 1 ); // $ExpectError
	zlastIndexOfTruthy.ndarray( false, x, 1, 1 ); // $ExpectError
	zlastIndexOfTruthy.ndarray( null, x, 1, 1 ); // $ExpectError
	zlastIndexOfTruthy.ndarray( {}, x, 1, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a Complex128Array...
{
	var x = new Complex128Array( [ 1.0, 2.0, 3.0 ] );

	zlastIndexOfTruthy.ndarray( x.length, '1', 1, 1 ); // $ExpectError
	zlastIndexOfTruthy.ndarray( x.length, true, 1, 1 ); // $ExpectError
	zlastIndexOfTruthy.ndarray( x.length, false, 1, 1 ); // $ExpectError
	zlastIndexOfTruthy.ndarray( x.length, null, 1, 1 ); // $ExpectError
	zlastIndexOfTruthy.ndarray( x.length, {}, 1, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a number...
{
	var x = new Complex128Array( [ 1.0, 2.0, 3.0 ] );

	zlastIndexOfTruthy.ndarray( x.length, x, '1', 1 ); // $ExpectError
	zlastIndexOfTruthy.ndarray( x.length, x, true, 1 ); // $ExpectError
	zlastIndexOfTruthy.ndarray( x.length, x, false, 1 ); // $ExpectError
	zlastIndexOfTruthy.ndarray( x.length, x, null, 1 ); // $ExpectError
	zlastIndexOfTruthy.ndarray( x.length, x, {}, 1 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	var x = new Complex128Array( [ 1.0, 2.0, 3.0 ] );

	zlastIndexOfTruthy.ndarray( x.length, x, 1, '1' ); // $ExpectError
	zlastIndexOfTruthy.ndarray( x.length, x, 1, true ); // $ExpectError
	zlastIndexOfTruthy.ndarray( x.length, x, 1, false ); // $ExpectError
	zlastIndexOfTruthy.ndarray( x.length, x, 1, null ); // $ExpectError
	zlastIndexOfTruthy.ndarray( x.length, x, 1, {} ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	zlastIndexOfTruthy.ndarray(); // $ExpectError
	zlastIndexOfTruthy.ndarray( 3 ); // $ExpectError
	zlastIndexOfTruthy.ndarray( 3, new Complex128Array( [ 1.0, 2.0, 3.0 ] ) ); // $ExpectError
	zlastIndexOfTruthy.ndarray( 3, new Complex128Array( [ 1.0, 2.0, 3.0 ] ), 1 ); // $ExpectError
	zlastIndexOfTruthy.ndarray( 3, new Complex128Array( [ 1.0, 2.0, 3.0 ] ), 1, 0, {} ); // $ExpectError
}
